// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/customers", wrapper.RegisterCustomer)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/microservices/{id}/deployments", wrapper.RegisterDeployment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/products", wrapper.ListProducts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/products", wrapper.RegisterProduct)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/products/{id}", wrapper.GetProduct)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/products/{id}/microservices", wrapper.RegisterMicroservice)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/products/{id}/projects", wrapper.ListProjectsOfProduct)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/products/{id}/tags", wrapper.GetProductTags)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/products/{id}/tags", wrapper.PutProductTags)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/projects", wrapper.RegisterProject)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/projects/{id}", wrapper.GetProject)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/projects/{id}/releases", wrapper.ListReleasesOfProject)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/projects/{id}/tags", wrapper.GetProjectTags)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/projects/{id}/tags", wrapper.PutProjectTags)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/releases", wrapper.ListReleases)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/releases", wrapper.RegisterRelease)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/releases/{id}", wrapper.GetRelease)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/releases/{id}/blast-radius", wrapper.GetBlastRadius)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/releases/{id}/tags", wrapper.GetReleaseTags)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/releases/{id}/tags", wrapper.PutReleaseTags)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tagged-releases", wrapper.ListTaggedReleases)
	})

	return r
}

